  "4-7-semicircle": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 320 240\" role=\"img\" aria-labelledby=\"t\">\n  <title id=\"t\">Circle with centre O. AB is a diameter. C is a point on the circle. Lines CA and CB meet at C with a right angle marked, 90 degrees. A dashed radius joins O to C.</title>\n  <circle cx=\"160.0\" cy=\"125.0\" r=\"90.0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/>\n  <line x1=\"70.0\" y1=\"125.0\" x2=\"250.0\" y2=\"125.0\" stroke=\"var(--t1-ink)\" stroke-width=\"2.2\"/>\n  <line x1=\"70.0\" y1=\"125.0\" x2=\"117.7\" y2=\"45.5\" stroke=\"currentColor\" stroke-width=\"1.8\"/>\n  <line x1=\"117.7\" y1=\"45.5\" x2=\"250.0\" y2=\"125.0\" stroke=\"currentColor\" stroke-width=\"1.8\"/>\n  <line x1=\"160.0\" y1=\"125.0\" x2=\"117.7\" y2=\"45.5\" stroke=\"var(--muted)\" stroke-width=\"1.3\" stroke-dasharray=\"5 3\"/>\n  <path d=\"M111.6,55.8 L121.9,62.0 L128.0,51.7\" fill=\"none\" stroke=\"var(--t1-ink)\" stroke-width=\"1.3\"/>\n  <circle cx=\"160.0\" cy=\"125.0\" r=\"3\" fill=\"currentColor\"/>\n  <circle cx=\"70.0\" cy=\"125.0\" r=\"3\" fill=\"currentColor\"/>\n  <circle cx=\"250.0\" cy=\"125.0\" r=\"3\" fill=\"currentColor\"/>\n  <circle cx=\"117.7\" cy=\"45.5\" r=\"3\" fill=\"currentColor\"/>\n  <g font-family=\"inherit\">\n    <text x=\"56.0\" y=\"130.0\" fill=\"currentColor\" font-size=\"14\" text-anchor=\"middle\">A</text>\n    <text x=\"264.0\" y=\"130.0\" fill=\"currentColor\" font-size=\"14\" text-anchor=\"middle\">B</text>\n    <text x=\"111.2\" y=\"38.2\" fill=\"currentColor\" font-size=\"14\" text-anchor=\"middle\">C</text>\n    <text x=\"160.0\" y=\"150.0\" fill=\"currentColor\" font-size=\"14\" text-anchor=\"middle\">O</text>\n    <text x=\"125.5\" y=\"81.6\" fill=\"var(--t1-ink)\" font-size=\"13\" text-anchor=\"middle\">90°</text>\n    <text x=\"220.0\" y=\"150.0\" fill=\"var(--t1-ink)\" font-size=\"12\" text-anchor=\"middle\">diameter</text>\n  </g>\n</svg>",
  "4-7-tangent-radius": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 320 240\" role=\"img\" aria-labelledby=\"t\">\n  <title id=\"t\">Circle with centre O. A tangent line touches the circle at P. The radius OP meets the tangent at a right angle, 90 degrees.</title>\n  <circle cx=\"140.0\" cy=\"115.0\" r=\"85.0\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"/>\n  <line x1=\"144.0\" y1=\"242.4\" x2=\"266.2\" y2=\"96.9\" stroke=\"var(--t3-ink)\" stroke-width=\"2.2\"/>\n  <line x1=\"140.0\" y1=\"115.0\" x2=\"205.1\" y2=\"169.6\" stroke=\"var(--t1-ink)\" stroke-width=\"2.2\"/>\n  <path d=\"M195.9,161.9 L188.2,171.1 L197.4,178.8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.3\"/>\n  <circle cx=\"140.0\" cy=\"115.0\" r=\"3\" fill=\"currentColor\"/>\n  <circle cx=\"205.1\" cy=\"169.6\" r=\"3\" fill=\"currentColor\"/>\n  <g font-family=\"inherit\">\n    <text x=\"126.0\" y=\"114.0\" fill=\"currentColor\" font-size=\"14\" text-anchor=\"middle\">O</text>\n    <text x=\"217.4\" y=\"184.9\" fill=\"currentColor\" font-size=\"14\" text-anchor=\"middle\">P</text>\n    <text x=\"171.2\" y=\"177.6\" fill=\"currentColor\" font-size=\"13\" text-anchor=\"middle\">90°</text>\n    <text x=\"156.6\" y=\"151.3\" fill=\"var(--t1-ink)\" font-size=\"12\" text-anchor=\"end\">radius</text>\n    <text x=\"276.2\" y=\"99.9\" fill=\"var(--t3-ink)\" font-size=\"12\" text-anchor=\"start\">tangent</text>\n  </g>\n</svg>",
  "9-3-quartiles": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 140\" role=\"img\" aria-labelledby=\"t\">\n  <title id=\"t\">Eleven ordered times in boxes, with the lower quartile 12.4, the median 13.0 and the upper quartile 14.1 marked, a bracket labelled IQR = 1.7, and the lower and upper halves labelled</title>\n  <g fill=\"var(--t4-ink)\" fill-opacity=\"0.16\" stroke=\"none\">\n    <rect x=\"72\" y=\"44\" width=\"30\" height=\"26\" />\n    <rect x=\"165\" y=\"44\" width=\"30\" height=\"26\" />\n    <rect x=\"258\" y=\"44\" width=\"30\" height=\"26\" />\n  </g>\n  <g stroke=\"currentColor\" stroke-width=\"1.2\" fill=\"none\">\n    <rect x=\"10\" y=\"44\" width=\"30\" height=\"26\" />\n    <rect x=\"41\" y=\"44\" width=\"30\" height=\"26\" />\n    <rect x=\"72\" y=\"44\" width=\"30\" height=\"26\" />\n    <rect x=\"103\" y=\"44\" width=\"30\" height=\"26\" />\n    <rect x=\"134\" y=\"44\" width=\"30\" height=\"26\" />\n    <rect x=\"165\" y=\"44\" width=\"30\" height=\"26\" />\n    <rect x=\"196\" y=\"44\" width=\"30\" height=\"26\" />\n    <rect x=\"227\" y=\"44\" width=\"30\" height=\"26\" />\n    <rect x=\"258\" y=\"44\" width=\"30\" height=\"26\" />\n    <rect x=\"289\" y=\"44\" width=\"30\" height=\"26\" />\n    <rect x=\"320\" y=\"44\" width=\"30\" height=\"26\" />\n  </g>\n  <g fill=\"currentColor\" font-size=\"10.5\" font-family=\"inherit\" text-anchor=\"middle\">\n    <text x=\"25\" y=\"61\">11.8</text>\n    <text x=\"56\" y=\"61\">12.2</text>\n    <text x=\"87\" y=\"61\">12.4</text>\n    <text x=\"118\" y=\"61\">12.7</text>\n    <text x=\"149\" y=\"61\">12.9</text>\n    <text x=\"180\" y=\"61\">13.0</text>\n    <text x=\"211\" y=\"61\">13.1</text>\n    <text x=\"242\" y=\"61\">13.5</text>\n    <text x=\"273\" y=\"61\">14.1</text>\n    <text x=\"304\" y=\"61\">14.6</text>\n    <text x=\"335\" y=\"61\">15.3</text>\n  </g>\n  <g stroke=\"var(--t4-ink)\" stroke-width=\"1.4\" fill=\"none\">\n    <polyline points=\"87,40 87,32 273,32 273,40\" />\n  </g>\n  <text x=\"180\" y=\"24\" fill=\"var(--t4-ink)\" font-size=\"12\" font-family=\"inherit\" text-anchor=\"middle\">IQR = 14.1 − 12.4 = 1.7</text>\n  <g fill=\"currentColor\" font-size=\"11.5\" font-family=\"inherit\" text-anchor=\"middle\">\n    <text x=\"87\" y=\"86\">lower quartile</text>\n    <text x=\"180\" y=\"86\">median</text>\n    <text x=\"273\" y=\"86\">upper quartile</text>\n  </g>\n  <g stroke=\"var(--muted)\" stroke-width=\"1\" fill=\"none\">\n    <polyline points=\"10,98 10,104 165,104 165,98\" />\n    <polyline points=\"196,98 196,104 351,104 351,98\" />\n  </g>\n  <g fill=\"var(--muted)\" font-size=\"11\" font-family=\"inherit\" text-anchor=\"middle\">\n    <text x=\"87.5\" y=\"120\">lower half</text>\n    <text x=\"273.5\" y=\"120\">upper half</text>\n  </g>\n</svg>"
